#include <stdio.h>

int main(void) {
    int age;
    if (scanf("%d", &age) != 1) {
        puts("Please enter an integer");
        return 1;
    }
    if (age < 0 || age > 130) {
        puts("Age is outside the accepted range");
        return 1;
    }
    printf("Age: %d\n", age);
    return 0;
}

#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    char line[64];
    if (fgets(line, sizeof line, stdin) == NULL) return 1;
    errno = 0;
    char *end;
    long value = strtol(line, &end, 10);
    if (end == line || errno == ERANGE || value < INT_MIN || value > INT_MAX) {
        puts("Invalid or out-of-range integer");
        return 1;
    }
    while (*end == ' ' || *end == '\\t' || *end == '\\n') ++end;
    if (*end != '\0') {
        puts("Unexpected trailing characters");
        return 1;
    }
    printf("Value: %ld\n", value);
    return 0;
}
